//! Backward compatibility guard: vaults created by an older Goldfish must keep opening.
//!
//! `tests/fixtures/vault-1.1.0/` is a real vault written by Goldfish 1.1.0 (SQLCipher
//! database, metadata sidecar with KDF parameters and recovery wrap, an encrypted
//! `.goldfish` export). Upgrades of the storage stack (rusqlite / SQLCipher / refinery),
//! the crypto crates (argon2, chacha20poly1305, hkdf, hmac, sha2, rand) or the serialization
//! must leave these tests green — otherwise existing users could no longer unlock.
//!
//! The fixture is committed and NEVER regenerated by an upgrade. Only a deliberate new
//! fixture version (`vault-<version>`) is added by running the ignored generator on the
//! old code: `cargo test -p goldfish-infrastructure --test compat_fixture -- --ignored`.
//! All secrets below are test data, not real credentials.

use std::path::{Path, PathBuf};
use std::sync::Arc;

use goldfish_application::VaultService;
use goldfish_domain::{CustomField, EntryDraft, EntryKind, KdfParams, PlaintextSecret};
use goldfish_infrastructure::{
    FileVaultMetadataRepository, KeyringStore, SqliteEntryStore, SystemClock,
};
use tempfile::tempdir;

const FIXTURE: &str = "vault-1.1.0";
const MASTER: &str = "goldfish-fixture-master-1.1.0";
const EXPORT_PASSWORD: &str = "goldfish-fixture-export-1.1.0";
const TOTP: &str = "JBSWY3DPEHPK3PXP";
const ATTACHMENT: &[u8] = b"Goldfish fixture attachment\n";

/// Cheap KDF so the suite stays fast; the parameters live in the fixture's metadata.
const fn fast() -> KdfParams {
    KdfParams {
        memory_kib: 256,
        iterations: 1,
        parallelism: 1,
    }
}

fn fixture_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join(FIXTURE)
}

fn wire(dir: &Path) -> VaultService {
    let store = Arc::new(SqliteEntryStore::new(dir.join("vault.db")));
    let meta = Arc::new(FileVaultMetadataRepository::new(
        dir.join("vault.meta.json"),
    ));
    VaultService::new(
        store.clone(),
        store,
        meta,
        Arc::new(SystemClock),
        Arc::new(KeyringStore::new()),
    )
}

/// Tests work on a copy: unlocking may touch the files and the fixture must stay pristine.
fn copy_fixture() -> tempfile::TempDir {
    let dir = tempdir().unwrap();
    for name in [
        "vault.db",
        "vault.meta.json",
        "export.goldfish",
        "recovery-code.txt",
    ] {
        std::fs::copy(fixture_dir().join(name), dir.path().join(name)).unwrap();
    }
    dir
}

#[tokio::test]
#[ignore = "writes a new fixture; run only on the OLD code when adding a fixture version"]
async fn generate_fixture() {
    let dir = fixture_dir();
    assert!(
        !dir.join("vault.db").exists(),
        "fixture {FIXTURE} already exists — never overwrite it"
    );
    std::fs::create_dir_all(&dir).unwrap();
    let svc = wire(&dir);
    let session = svc.create_vault(MASTER, fast()).await.unwrap();

    let folder = svc.create_folder("Práce").await.unwrap();
    let tag = svc.create_tag("2FA").await.unwrap();

    let mut login = EntryDraft::new(
        "E-mail",
        "jana@example.com",
        PlaintextSecret::from("Heslo-Ž1ťčř!"),
    )
    .unwrap();
    login.url = Some("https://mail.example.com".into());
    login.totp_secret = Some(PlaintextSecret::from(TOTP));
    login.notes = Some(PlaintextSecret::from(
        "Poznámka s diakritikou: příliš žluťoučký kůň",
    ));
    login.folder_id = Some(folder.id);
    login.tags = vec![tag.id];
    login.favorite = true;
    login.custom_fields = vec![CustomField {
        label: "PIN".into(),
        value: PlaintextSecret::from("4321"),
        hidden: true,
    }];
    let login = svc.add_entry(&session, login).await.unwrap();

    let mut note = EntryDraft::new("Kódy pro obnovení", "", PlaintextSecret::from("")).unwrap();
    note.kind = EntryKind::SecureNote;
    note.notes = Some(PlaintextSecret::from("AAAA-BBBB-CCCC"));
    svc.add_entry(&session, note).await.unwrap();

    svc.add_attachment(&session, login.id, "priloha.txt", ATTACHMENT)
        .await
        .unwrap();

    let export = svc
        .export_vault(&session, EXPORT_PASSWORD, fast())
        .await
        .unwrap();
    std::fs::write(dir.join("export.goldfish"), &export.bytes).unwrap();

    let code = svc.enable_recovery(&session).await.unwrap();
    std::fs::write(dir.join("recovery-code.txt"), code.as_str()).unwrap();

    drop(session);
    svc.lock().await.unwrap();
}

#[tokio::test]
async fn opens_vault_from_1_1_0_and_decrypts_everything() {
    let dir = copy_fixture();
    let svc = wire(dir.path());
    assert!(svc.vault_exists().await.unwrap());

    let session = svc.unlock_vault(MASTER).await.unwrap();

    let summaries = svc.list_entries(None).await.unwrap();
    assert_eq!(summaries.len(), 2);
    let login_id = summaries.iter().find(|s| s.title == "E-mail").unwrap().id;
    let login = svc.get_entry(&session, login_id).await.unwrap();
    assert_eq!(login.username, "jana@example.com");
    assert_eq!(login.password.expose(), "Heslo-Ž1ťčř!");
    assert_eq!(login.totp_secret.as_ref().unwrap().expose(), TOTP);
    assert_eq!(
        login.notes.as_ref().unwrap().expose(),
        "Poznámka s diakritikou: příliš žluťoučký kůň"
    );
    assert_eq!(login.custom_fields[0].label, "PIN");
    assert_eq!(login.custom_fields[0].value.expose(), "4321");
    assert!(login.favorite);

    let folders = svc.list_folders().await.unwrap();
    assert_eq!(
        login.folder_id,
        Some(folders.iter().find(|f| f.name == "Práce").unwrap().id)
    );
    assert_eq!(svc.list_tags().await.unwrap()[0].name, "2FA");

    let attachments = svc.list_attachments(login_id).await.unwrap();
    let (name, bytes) = svc
        .open_attachment(&session, attachments[0].id)
        .await
        .unwrap();
    assert_eq!(name, "priloha.txt");
    assert_eq!(bytes.as_slice(), ATTACHMENT);
}

#[tokio::test]
async fn wrong_master_password_is_still_rejected() {
    let dir = copy_fixture();
    assert!(wire(dir.path())
        .unlock_vault("wrong-password")
        .await
        .is_err());
}

#[tokio::test]
async fn imports_export_file_from_1_1_0() {
    let fixture = copy_fixture();
    let bytes = std::fs::read(fixture.path().join("export.goldfish")).unwrap();

    let dir = tempdir().unwrap();
    let svc = wire(dir.path());
    let session = svc.create_vault("new-vault-master", fast()).await.unwrap();
    let imported = svc
        .import_vault_file(&session, &bytes, EXPORT_PASSWORD)
        .await
        .unwrap();

    assert_eq!(imported, 2);
    let summaries = svc.list_entries(None).await.unwrap();
    let id = summaries.iter().find(|s| s.title == "E-mail").unwrap().id;
    assert_eq!(
        svc.get_entry(&session, id).await.unwrap().password.expose(),
        "Heslo-Ž1ťčř!"
    );
}

#[tokio::test]
async fn recovery_code_from_1_1_0_still_resets_the_master_password() {
    let dir = copy_fixture();
    let code = std::fs::read_to_string(dir.path().join("recovery-code.txt")).unwrap();
    let svc = wire(dir.path());

    let session = svc
        .unlock_with_recovery(code.trim(), "brand-new-master")
        .await
        .unwrap();
    assert_eq!(svc.list_entries(None).await.unwrap().len(), 2);
    drop(session);
    svc.lock().await.unwrap();

    assert!(wire(dir.path())
        .unlock_vault("brand-new-master")
        .await
        .is_ok());
}
